  "settings.modelProvider.help.contextWindow":
    "Capacité de contexte que le modèle peut traiter en une fois, en jetons. ZCode s’en sert pour gérer le contexte.\nNe dépassez pas la limite réelle du modèle.",
  "settings.modelProvider.help.maxOutputTokens":
    "Nombre maximal de jetons qu’une requête au modèle peut générer.\nNe dépassez pas la limite réelle du modèle.",
  "settings.modelProvider.help.inputModalities":
    "Définissez les types de contenu que le modèle peut recevoir :\n\n- **Texte** : reçoit du texte. Obligatoire.\n- **Images** : reçoit des images.\n- **Vidéo** : reçoit des vidéos.\n- **PDF** : reçoit directement des documents PDF.",
  "settings.modelProvider.help.outputModalities":
    "Type de contenu des réponses du modèle. Seul le texte est pris en charge pour l’instant.",
  "settings.modelProvider.help.capabilities":
    "- **Sortie structurée** : prend en charge les contraintes JSON Schema sur les champs, types et structure de la sortie.\n- **Recherche web native** : prend en charge la recherche web intégrée de l’API du modèle.\n- **Messages système en cours de conversation** : permet d’insérer des instructions système pendant la conversation.\n\nN’activez pas de capacités que le modèle ne prend pas en charge.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Définissez les niveaux de raisonnement disponibles dans le chat. **Ils doivent être classés du plus faible au plus fort effort de raisonnement**.\nNe configurez pas de niveaux que le modèle ne prend pas en charge.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Utilisez une expression CEL pour convertir le niveau de raisonnement actuel, `reasoningLevel`, en champs de la requête à l’API du modèle. L’objet JSON renvoyé par l’expression est fusionné dans le corps de la requête.",
  "settings.modelProvider.help.advanced":
    "**Schéma d’outils MFJS** : active la compatibilité Moonshot Flavored JSON Schema, généralement utilisée par l’API Kimi de Moonshot. À activer uniquement si l’API du modèle l’exige.",
